def _save_data(path, config_dict, wordlists):
    """
    Saves data to a directory.
    Raises Exception on failure (e.g. if data is corrupted).
    """
    if not os.path.exists(path):
        os.makedirs(path)
    for filename in os.listdir(path):
        if filename.endswith('.txt'):
            os.remove(os.path.join(path, filename))
    for filename in os.listdir(path):
        if filename.endswith('.json'):
            os.remove(os.path.join(path, filename))
    for wordlist in wordlists:
        with open(os.path.join(path, 'words.txt'), 'a') as f:
            for word in wordlist:
                f.write(word + '\n')
    with open(os.path.join(path, 'config.json'), 'w') as f:
        json.dump(config_dict, f)


def _get_data_path(app_name):
    """
    Returns path to the data directory.
    """
    return os.path.join(os.path.expanduser('~'), '.%s' % app_name)


def _get_config_path(app_name):
    """
    Returns path to the config file.
    """
    return os.path.join(_get_data_path(app_name), 'config.json
